def normalize_language(language: str) -> str:
    candidate = (language or "en").replace("_", "-").split("-", 1)[0].lower()
    return candidate if candidate in SUPPORTED_LANGUAGES else "en"


def tr(key: str, language: str = "en") -> str:
    lang = normalize_language(language)
    return _CATALOG.get(lang, {}).get(key, _CATALOG["en"].get(key, key))


def navigation(language: str = "en"):
    lang = normalize_language(language)
    return [(key, _CATALOG[lang].get("nav." + key, _CATALOG["en"]["nav." + key])) for key in _NAV_KEYS]
